def transform(grid):
    """Erase the row containing the longest uninterrupted run of foreground cells."""
    if not grid:
        return []
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best_len = -1
    target = 0
    for r, row in enumerate(grid):
        run = longest = 0
        for value in row:
            if value != bg:
                run += 1
                longest = max(longest, run)
            else:
                run = 0
        if longest > best_len:
            best_len, target = longest, r
    out = [row[:] for row in grid]
    out[target] = [bg] * len(out[target])
    return out

